`backend/src/main/java/dev/jclawlor/FitnessGoals/controller/LiftingExerciseController.java`
```java
// java
package dev.jclawlor.FitnessGoals.controller;

import java.util.List;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import dev.jclawlor.FitnessGoals.dto.LiftingExerciseDto;
import dev.jclawlor.FitnessGoals.service.LiftingExerciseService;
import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/lifting-exercises")
public class LiftingExerciseController {

    private final LiftingExerciseService liftingExerciseService;

    public LiftingExerciseController(LiftingExerciseService liftingExerciseService) {
        this.liftingExerciseService = liftingExerciseService;
    }

    @PostMapping
    public ResponseEntity<LiftingExerciseDto> addLifting(@Valid @RequestBody LiftingExerciseDto dto) {
        final LiftingExerciseDto saved = liftingExerciseService.addLiftingExercise(dto);
        return ResponseEntity.ok(saved);
    }

    @GetMapping
    public ResponseEntity<List<LiftingExerciseDto>> getAllLiftingExercises() {
        return ResponseEntity.ok(liftingExerciseService.getAllLiftingExercises());
    }

    @GetMapping("/{id}")
    public ResponseEntity<LiftingExerciseDto> getLiftingExerciseById(@PathVariable Long id) {
        return ResponseEntity.ok(liftingExerciseService.getLiftingExerciseById(id));
    }

    @GetMapping("/name/{name}")
    public ResponseEntity<LiftingExerciseDto> getLiftingExerciseByName(@PathVariable String name) {
        return ResponseEntity.ok(liftingExerciseService.getLiftingExerciseByName(name));
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteExercise(@PathVariable Long id) {
        liftingExerciseService.deleteLiftingExercise(id);
        return ResponseEntity.ok().build();
    }

    @PutMapping("/{id}")
    public ResponseEntity<LiftingExerciseDto> updateLifting(@PathVariable Long id, @Valid @RequestBody LiftingExerciseDto dto) {
        LiftingExerciseDto updated = liftingExerciseService.updateLiftingExercise(id, dto);
        return ResponseEntity.ok(updated);
    }
}
```

Also verify your main application class is in `dev.jclawlor.FitnessGoals` (root package) so Spring Boot's component scan includes `service.impl`.
